new='''/**
 * The three index writers below own the "is this searchable?" decision, so
 * every caller (event listeners, the rebuild job, reindex requests) gets the
 * same answer: a project is searchable while it is live, an issue while it and
 * its project are live, a comment while it, its issue and that issue's project
 * are live. Each returns whether the subject ended up in the index; a subject
 * that is not searchable is taken out of the index rather than left behind.
 */
export async function indexIssue(
  orgId: OrgId,
  issue: Issue,
): Promise<boolean> {
  if (!(await isIssueSearchable(orgId, issue))) {
    await removeFromIndex(orgId, "issue", issue.id);
    return false;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\\n"),
    issue.projectId,
  );
  return true;
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<boolean> {
  if (!(await isCommentSearchable(orgId, comment))) {
    await removeFromIndex(orgId, "comment", comment.id);
    return false;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
  return true;
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<boolean> {
  if (!isLive(project)) {
    await removeFromIndex(orgId, "project", project.id);
    return false;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\\n"),
    project.id,
  );
  return true;
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/** Rows read per page when a listener or the rebuild walks a subtree. */
const INDEX_PAGE_SIZE = 100;

/**
 * Visits every item of a cursor-paged listing, page after page. The listing
 * is only ever as long as its cursor says, so a workspace larger than one page
 * is walked in full.
 */
export async function forEachPage<T>(
  fetch: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;

  do {
    const page: Page<T> = await fetch(cursor);
    for (const item of page.items) await visit(item);

    if (page.nextCursor === cursor) break;
    cursor = page.nextCursor;
  } while (cursor !== null);
}

/** Re-evaluates an issue and every comment on it against current state. */
export async function reindexIssueTree(
  orgId: OrgId,
  issue: Issue,
): Promise<void> {
  await indexIssue(orgId, issue);
  await forEachPage(
    (cursor) =>
      commentRepo.listIssueComments(orgId, issue.id, {
        limit: INDEX_PAGE_SIZE,
        cursor,
      }),
    async (comment) => {
      await indexComment(orgId, comment);
    },
  );
}

/**
 * Re-evaluates a project and everything under it. Archiving a project takes
 * its issues and comments out of search whether or not its issues were
 * archived with it, and restoring it brings back only what is live again —
 * issues archived earlier stay archived, so they and their comments stay out.
 */
export async function reindexProjectTree(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) {
    await indexProject(orgId, project);
  } else {
    await removeFromIndex(orgId, "project", projectId);
  }

  await forEachPage(
    (cursor) =>
      issueRepo.listIssues({
        orgId,
        projectId,
        includeArchived: true,
        limit: INDEX_PAGE_SIZE,
        cursor,
      }),
    (issue) => reindexIssueTree(orgId, issue),
  );
}

/**
 * Brings one subject in line with the database: re-read it, index it if it is
 * searchable and drop it from the index if it is not (or no longer exists).
 */
export async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  switch (subjectKind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as IssueId);
      if (issue) await indexIssue(orgId, issue);
      else await removeFromIndex(orgId, "issue", subjectId);
      return;
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as CommentId,
      );
      if (comment) await indexComment(orgId, comment);
      else await removeFromIndex(orgId, "comment", subjectId);
      return;
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as ProjectId,
      );
      if (project) await indexProject(orgId, project);
      else await removeFromIndex(orgId, "project", subjectId);
      return;
    }
  }
}

async function isProjectLive(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<boolean> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  return project !== null && isLive(project);
}

async function isIssueSearchable(orgId: OrgId, issue: Issue): Promise<boolean> {
  return isLive(issue) && (await isProjectLive(orgId, issue.projectId));
}

async function isCommentSearchable(
  orgId: OrgId,
  comment: Comment,
): Promise<boolean> {
  if (!isLive(comment)) return false;

  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  return issue !== null && (await isIssueSearchable(orgId, issue));
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await reindexSubject(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("issue.updated", async (payload) => {
      await reindexSubject(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (issue) await reindexIssueTree(payload.orgId, issue);
      else await removeFromIndex(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      await reindexSubject(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("comment.updated", async (payload) => {
      await reindexSubject(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      await reindexSubject(payload.orgId, "project", payload.projectId);
    }),
    subscribe("project.updated", async (payload) => {
      await reindexSubject(payload.orgId, "project", payload.projectId);
    }),
    subscribe("project.archived", async (payload) => {
      await reindexProjectTree(payload.orgId, payload.projectId);
    }),
    subscribe("project.restored", async (payload) => {
      await reindexProjectTree(payload.orgId, payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      await reindexSubject(payload.orgId, payload.subjectKind, payload.subjectId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

