 */
export async function reindexProjectTree(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) {
    await indexProject(orgId, project);
  } else {
    await removeFromIndex(orgId, "project", projectId);
  }

  await forEachPage(
    (cursor) =>
      issueRepo.listIssues({
        orgId,
        projectId,
        includeArchived: true,
        limit: INDEX_PAGE_SIZE,
        cursor,
      }),
    (issue) => reindexIssueTree(orgId, issue),
  );
}

/**
 * Brings one subject in line with the database: re-read it, index it if it is
 * searchable and drop it from the index if it is not (or no longer exists).
 */
export async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  switch (subjectKind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as IssueId);
      if (issue) await indexIssue(orgId, issue);
      else await removeFromIndex(orgId, "issue", subjectId);
      return;
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as CommentId,
      );
      if (comment) await indexComment(orgId, comment);
      else await removeFromIndex(orgId, "comment", subjectId);
      return;
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as ProjectId,
      );
      if (project) await indexProject(orgId, project);
      else await removeFromIndex(orgId, "project", subjectId);
      return;
    }
  }
}

async function isProjectLive(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<boolean> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  return project !== null && isLive(project);
}

async function isIssueSearchable(orgId: OrgId, issue: Issue): Promise<boolean> {
  return isLive(issue) && (await isProjectLive(orgId, issue.projectId));
}

async function isCommentSearchable(
  orgId: OrgId,
  comment: Comment,
): Promise<boolean> {
  if (!isLive(comment)) return false;

  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  return issue !== null && (await isIssueSearchable(orgId, issue));
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await reindexSubject(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("issue.updated", async (payload) => {
      await reindexSubject(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (issue) await reindexIssueTree(payload.orgId, issue);
      else await removeFromIndex(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      await reindexSubject(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("comment.updated", async (payload) => {
      await reindexSubject(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      await reindexSubject(payload.orgId, "project", payload.projectId);
    }),
    subscribe("project.updated", async (payload) => {
      await reindexSubject(payload.orgId, "project", payload.projectId);
    }),
    subscribe("project.archived", async (payload) => {
      await reindexProjectTree(payload.orgId, payload.projectId);
    }),
    subscribe("project.restored", async (payload) => {
      await reindexProjectTree(payload.orgId, payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      await reindexSubject(payload.orgId, payload.subjectKind, payload.subjectId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

