/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  forEachPage,
  indexComment,
  indexIssue,
  indexProject,
  reindexSubject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { OrgId } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

function subjectKey(kind: SearchSubjectKind, subjectId: string): string {
  return `${kind}:${subjectId}`;
}

/**
 * Walks one tenant's projects, issues and comments — every page of each — and
 * hands every row to the index writers. Scoped to a single org on purpose: a
 * full-fleet reindex is a sequence of these, so one slow tenant cannot stall
 * the rest, and nothing here reads or writes another org's rows.
 *
 * Archived rows are read too: the rebuild is what brings a restored project's
 * content back, so it hands every row to the index writers and leaves the
 * "is this searchable?" decision to them.
 *
 * A rebuild has to leave *exactly* the searchable entries, so afterwards any
 * entry the walk did not vouch for (a document whose subject is gone, or one
 * that was never reachable) is re-checked against the database and dropped
 * unless it turns out to be searchable after all.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const vouched = new Set<string>();

    await forEachPage(
      (cursor) =>
        projectRepo.listProjects({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        }),
      async (project) => {
        try {
          if (await indexProject(orgId, project)) {
            vouched.add(subjectKey("project", project.id));
          }
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await forEachPage(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        }),
      async (issue) => {
        try {
          if (await indexIssue(orgId, issue)) {
            vouched.add(subjectKey("issue", issue.id));
          }
          result.processed += 1;

          await forEachPage(
            (cursor) =>
              commentRepo.listIssueComments(orgId, issue.id, {
                limit: PAGE_SIZE,
                cursor,
              }),
            async (comment) => {
              if (await indexComment(orgId, comment)) {
                vouched.add(subjectKey("comment", comment.id));
              }
              result.processed += 1;
            },
          );
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    const indexed = await searchRepo.listIndexedSubjects(orgId);
    for (const { subjectKind, subjectId } of indexed) {
      if (vouched.has(subjectKey(subjectKind, subjectId))) continue;

      try {
        await reindexSubject(orgId, subjectKind, subjectId);
      } catch (error) {
        result.failed += 1;
        logger.error("failed to reconcile stale search entry", {
          subjectKind,
          subjectId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
