/**
 * What search may show: a project while it is live, an issue while it and its
 * project are live, a comment while it, its issue and that project are live —
 * through archiving, restoring, later writes and the index rebuild.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";
import type { Project } from "@/types/project";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

async function find(tenant: Tenant, q: string) {
  const page = await searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds: ["issue", "comment", "project"],
    limit: 100,
    cursor: null,
  });
  return { total: page.total, ids: page.items.map((item) => item.id) };
}

async function newProject(tenant: Tenant, name: string): Promise<Project> {
  return projectService.createProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    name,
    slug: name.toLowerCase(),
    key: name.slice(0, 4).toUpperCase(),
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

async function newIssue(tenant: Tenant, project: Project, title: string): Promise<Issue> {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, project.id, { title }),
  );
}

async function newComment(tenant: Tenant, issue: Issue, body: string) {
  return commentService.createComment(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    body,
    parentId: null,
    mentionedUserIds: [],
  });
}

describe("archiving an issue", () => {
  it("takes its comments out of search with it", async () => {
    const tenant = await createTenant("vis-issue", "growth");
    const issue = await newIssue(tenant, tenant.project, "Vis issue alpha");
    await newComment(tenant, issue, "Vis comment alpha");

    expect((await find(tenant, "alpha")).total).toBe(2);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    expect(await find(tenant, "alpha")).toEqual({ total: 0, ids: [] });
  });
});

describe("archiving a project", () => {
  it.each([true, false])(
    "hides the project, its issues and comments (archiveIssues: %s)",
    async (archiveIssues) => {
      const tenant = await createTenant(`vis-proj-${archiveIssues}`, "growth");
      const project = await newProject(tenant, `Bravo${archiveIssues}`);
      const issue = await newIssue(tenant, project, "Bravo issue");
      await newComment(tenant, issue, "Bravo comment");
      expect((await find(tenant, "Bravo")).total).toBe(3);

      await projectService.archiveProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: project.id,
        archiveIssues,
      });

      expect((await find(tenant, "Bravo")).total).toBe(0);
    },
  );

  it("keeps later comments and edits on surviving issues hidden", async () => {
    const tenant = await createTenant("vis-later", "growth");
    const project = await newProject(tenant, "Charlie");
    const issue = await newIssue(tenant, project, "Charlie issue");
    const comment = await newComment(tenant, issue, "Charlie first");

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });

    await newComment(tenant, issue, "Charlie second");
    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "Charlie edited",
    });
    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "Charlie retitled",
    });

    expect((await find(tenant, "Charlie")).total).toBe(0);
  });
});

describe("restoring a project", () => {
  it("brings back the project and what is live, not what was archived", async () => {
    const tenant = await createTenant("vis-restore", "growth");
    const project = await newProject(tenant, "Delta");
    const kept = await newIssue(tenant, project, "Delta kept");
    const keptComment = await newComment(tenant, kept, "Delta kept comment");
    const early = await newIssue(tenant, project, "Delta early");
    await newComment(tenant, early, "Delta early comment");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, early.id);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });
    expect((await find(tenant, "Delta")).total).toBe(0);

    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, project.id);

    const hits = await find(tenant, "Delta");
    expect(hits.total).toBe(3);
    expect(hits.ids.sort()).toEqual([project.id, kept.id, keptComment.id].sort());
  });

  it("does not revive issues archived together with the project", async () => {
    const tenant = await createTenant("vis-restore-all", "growth");
    const project = await newProject(tenant, "Echo");
    const issue = await newIssue(tenant, project, "Echo issue");
    await newComment(tenant, issue, "Echo comment");

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: true,
    });
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, project.id);

    expect((await find(tenant, "Echo")).ids).toEqual([project.id]);
  });
});

describe("editing", () => {
  it("re-indexes an edited comment and a renamed project", async () => {
    const tenant = await createTenant("vis-edit", "growth");
    const project = await newProject(tenant, "Foxtrot");
    const issue = await newIssue(tenant, project, "Foxtrot issue");
    const comment = await newComment(tenant, issue, "Golf original");

    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "Golf rewritten",
    });
    await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      name: "Hotel",
    });

    expect((await find(tenant, "original")).total).toBe(0);
    expect((await find(tenant, "rewritten")).ids).toEqual([comment.id]);
    expect((await find(tenant, "Foxtrot")).ids).toEqual([issue.id]);
    expect((await find(tenant, "Hotel")).ids).toEqual([project.id]);
  });
});

describe("rebuilding the index", () => {
  it("leaves exactly the searchable entries, however many pages that takes", async () => {
    const tenant = await createTenant("vis-rebuild", "enterprise");
    const other = await createTenant("vis-rebuild-other", "growth");
    const otherIssue = await newIssue(other, other.project, "Juliet other tenant");

    const live = await newProject(tenant, "Kilo");
    const doomed = await newProject(tenant, "Lima");
    const expected = new Set<string>([live.id]);

    for (let i = 0; i < 130; i += 1) {
      const issue = await newIssue(tenant, live, `Kilo issue ${i}`);
      expected.add(issue.id);
      if (i % 10 === 0) {
        const comment = await newComment(tenant, issue, `Kilo comment ${i}`);
        expected.add(comment.id);
      }
    }

    const archivedIssue = await newIssue(tenant, live, "Kilo archived");
    await newComment(tenant, archivedIssue, "Kilo archived comment");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedIssue.id);

    const doomedIssue = await newIssue(tenant, doomed, "Lima issue");
    await newComment(tenant, doomedIssue, "Lima comment");
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: doomed.id,
      archiveIssues: false,
    });

    // Drift: entries with nothing behind them, plus a duplicate of a live one.
    await searchRepo.upsertSearchDocument(tenant.org.id, "issue", "ghost", "Kilo ghost", null);
    await searchRepo.upsertSearchDocument(tenant.org.id, "comment", "ghost-comment", "Kilo ghost", null);
    await searchRepo.upsertSearchDocument(tenant.org.id, "issue", archivedIssue.id, "Kilo archived", live.id);

    // Wipe a live entry too, so the rebuild has to bring it back.
    await searchRepo.deleteSearchDocument(tenant.org.id, "project", live.id);

    const otherBefore = await searchRepo.countIndexed(other.org.id);

    const result = await runSearchReindexJob(tenant.org.id);
    expect(result.failed).toBe(0);

    const indexed = await searchRepo.listIndexedSubjects(tenant.org.id);
    expect(new Set(indexed.map((row) => row.subjectId))).toEqual(expected);
    expect(await searchRepo.countIndexed(tenant.org.id)).toBe(expected.size);

    expect((await find(tenant, "Kilo")).total).toBe(expected.size);
    expect((await find(tenant, "Lima")).total).toBe(0);
    expect((await find(tenant, "archived")).total).toBe(0);

    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherBefore);
    expect((await find(other, "Juliet")).ids).toEqual([otherIssue.id]);
  });
});
